import{_ as i,o as s,c as l,j as a,a as o,G as r,aa as d,B as c}from"./chunks/framework.VLjJFeoF.js";const f=JSON.parse('{"title":"vite","description":"","frontmatter":{},"headers":[],"relativePath":"docs/front-end/modules/vite/basic.md","filePath":"docs/front-end/modules/vite/basic.md","lastUpdated":1770685239000}'),n={name:"docs/front-end/modules/vite/basic.md"};function p(m,e,v,h,u,b){const t=c("ArticleMetadata");return s(),l("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1770685239000"},[e[0]||(e[0]=a("h1",{id:"vite",tabindex:"-1"},[o("vite "),a("a",{class:"header-anchor",href:"#vite","aria-label":'Permalink to "vite"'},"​")],-1)),r(t,{article:{}}),e[1]||(e[1]=d('<h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><h3 id="什么是构建工具" tabindex="-1">什么是构建工具？ <a class="header-anchor" href="#什么是构建工具" aria-label="Permalink to &quot;什么是构建工具？&quot;">​</a></h3><p>浏览器只认识html、css、js，如果要使用其他文件，比如图片、框架等，就需要使用构建工具进行处理。</p><p>企业项目具有复杂的构建需求，比如：</p><ol><li>typescript 如果遇到ts文件需要使用tsc将ts编译成js，</li><li>React/Vue 安装react complier/ vue compiler, 将jsx/vue文件转化成render函数</li><li>less/scss/postcss 安装sass-loader/less-loader等编译工具</li><li>语法降级 babel swc 将es新语法转化旧版浏览器可以接受的语法</li><li>体积优化 uglifyjs 压缩代码</li><li>...</li></ol><p>vite webpack 就集成了以上所有功能，并且提供了开箱即用的开发环境，可以快速上手。</p><p>构建工具承担了那些工作？</p><ol><li>模块化开发支持 支持从node_modules导入代码 + 多种模块化支持</li><li>处理代码兼容 比如babel降级 less ts语法转换(集成语法处理工具来自动化处理)</li><li>提高项目性能 代码压缩合并 tree-shaking</li><li>优化开发体验 热更新 开发服务器(跨域等问题) 代码错误提示 代码格式化</li><li>自动化测试 支持jest/mocha/ava/cypress等测试框架</li></ol><h2 id="vite相较于webpack的优势" tabindex="-1">vite相较于webpack的优势 <a class="header-anchor" href="#vite相较于webpack的优势" aria-label="Permalink to &quot;vite相较于webpack的优势&quot;">​</a></h2><p>构建大型应用时 JavaScript启动开发服务器时间过长，即使使用HMR(热更新)， 文件修改效果也需要几秒钟才能反映过来</p><h2 id="vite的预构建" tabindex="-1">vite的预构建 <a class="header-anchor" href="#vite的预构建" aria-label="Permalink to &quot;vite的预构建&quot;">​</a></h2><p>开发环境每次预购建的相对路径都是正确的 生产环境直接全权交给rollup进行打包</p><p><strong>依赖预购建</strong></p><p>vite会找到对应依赖，然后调用esbuild(对js语法处理的一个库),将其他规范的代码转成esmodule规范，然后放到当前目录的node_modules/.vite/deps中，同时对esmodule规范的各个模板进行统一集成。</p><ol><li>不同的第三方包有不同的导出格式 (vite无法约束)</li><li>对路径的处理可以使用.vite/deps，方便路径重写</li><li>网络多包传输的性能问题(原生es不能直接支持node_modules的原因) 有了依赖预购建后就可以尽可能把它集成到一个或几个文件中进行import/export，减少网络请求。</li></ol>',15))])}const k=i(n,[["render",p]]);export{f as __pageData,k as default};
